import sys
sys.setrecursionlimit(1000000)

def rec(a, arr, i, j, n, m):
	if arr[i][j] == 1:
		return
	arr[i][j] = 1
	if i - 1 >= 0:
		if a[i - 1][j] == a[i][j]:
			rec(a, arr, i - 1, j, n, m)
	if i + 1 < n:
		if a[i + 1][j] == a[i][j]:
			rec(a, arr, i + 1, j, n, m)
	if j - 1 >= 0:
		if a[i][j - 1] == a[i][j]:
			rec(a, arr, i, j - 1, n, m)
	if j + 1 < m:
		if a[i][j + 1] == a[i][j]:
			rec(a, arr, i, j + 1, n, m)
for x in range(int(input())):
	(n, m) = [int(i) for i in input().strip().split()]
	a = [[int(i) for i in input().strip().split()] for j in range(n)]
	arr = [[0] * m for i in range(n)]
	ans = 0
	for i in range(n):
		for j in range(m):
			if arr[i][j] == 0:
				if i - 1 >= 0:
					if a[i - 1][j] > a[i][j]:
						rec(a, arr, i, j, n, m)
						continue
				if i + 1 < n:
					if a[i + 1][j] > a[i][j]:
						rec(a, arr, i, j, n, m)
						continue
				if j - 1 >= 0:
					if a[i][j - 1] > a[i][j]:
						rec(a, arr, i, j, n, m)
						continue
				if j + 1 < m:
					if a[i][j + 1] > a[i][j]:
						rec(a, arr, i, j, n, m)
						continue
	for i in range(n):
		for j in range(m):
			if arr[i][j] == 0:
				rec(a, arr, i, j, n, m)
				ans += 1
	print(ans)
